// Zweck: prüft einen Auftrag aus dem Dashboard, bevor K1 startet. Gleiche Grenzen wie im Formular von K1.
const cfg = $('Konfiguration [Edit Fields]').first().json;
// Warum Typprüfung: ein Body, der kein Objekt ist, soll eine 400 ergeben, keinen Absturz.
const rawBody = $input.first().json.body;
const b = (rawBody && typeof rawBody === 'object' && !Array.isArray(rawBody)) ? rawBody : {};
const s = v => (typeof v === 'string' ? v.trim() : '');
// Warum Research (14.10.2026): dieselben 5 Quellenarten wie im n8n-Formular von K1; bei Research recherchiert K1 selbst, die Quelle bleibt optional wie bei Thema.
const types = ['Thema', 'Artikel-Link', 'YouTube-Link', 'Eigener Text', 'Research'];
const job = {
  customer_code: s(b.customer_code).toLowerCase(),
  source_type: s(b.source_type),
  topic: s(b.topic),
  source: s(b.source),
  note: s(b.note),
};
const errors = [];
// Warum hier und nicht erst in K1: ein ungültiger Auftrag kostet so keinen Modellaufruf.
if (!/^[a-z0-9-]{2,40}$/.test(job.customer_code)) errors.push('Kunde fehlt oder ist ungültig.');
if (!types.includes(job.source_type)) errors.push('Quellenart ist unbekannt.');
if (job.topic.length < 3 || job.topic.length > 200) errors.push('Das Thema braucht 3 bis 200 Zeichen.');
if (job.source_type !== 'Thema' && job.source_type !== 'Research' && !job.source) errors.push('Für diese Quellenart fehlt die Quelle.');
// Warum checkLink (14.10.2026): wortgleich mit der Prüffunktion im Browser (Seite bauen), damit Formular und Server dasselbe Ergebnis liefern.
// Ohne new URL, weil der Parser in der n8n-Code-Umgebung auch gültige Adressen ablehnte (Testlauf 1099). Rückgabe: Adresse mit Host als Punycode in Kleinschrift oder null;
// Host-Regel wie der URL-Parser (NFC, Kleinschrift, Punycode nur gültig dekodierbar), K1 bekommt immer einen reinen ASCII-Host.
// YouTube nur in den Formen, die K1 im Knoten Video-ID ermitteln versteht (watch?v=, youtu.be/, shorts/, embed/), und nur, wenn K1s Muster dieselbe Kennung findet.
function checkLink(t,s){function dg(d){return String.fromCharCode(d<26?97+d:22+d)}function ad(d,n,f){d=f?Math.floor(d/700):d>>1;d+=Math.floor(d/n);var k=0;while(d>455){d=Math.floor(d/35);k+=36}return k+Math.floor(36*d/(d+38))}function enc(u){var cp=Array.from(u).map(function(c){return c.codePointAt(0)}),n=128,dl=0,bi=72,o=[],b=0,i,h;for(i=0;i<cp.length;i++)if(cp[i]<128){o.push(String.fromCharCode(cp[i]));b++}h=b;if(b>0)o.push("-");while(h<cp.length){var m=1114112;for(i=0;i<cp.length;i++)if(cp[i]>=n&&cp[i]<m)m=cp[i];dl+=(m-n)*(h+1);n=m;for(i=0;i<cp.length;i++){if(cp[i]<n)dl++;if(cp[i]===n){var q=dl;for(var k=36;;k+=36){var tt=k<=bi?1:(k>=bi+26?26:k-bi);if(q<tt)break;o.push(dg(tt+(q-tt)%(36-tt)));q=Math.floor((q-tt)/(36-tt))}o.push(dg(q));bi=ad(dl,h+1,h===b);dl=0;h++}}dl++;n++}return o.join("")}function dec(x){var n=128,i=0,bi=72,o=[],d=x.lastIndexOf("-"),j,p;if(d===0)return null;for(j=0;j<(d>0?d:0);j++){if(x.charCodeAt(j)>=128)return null;o.push(x.charCodeAt(j))}p=d>0?d+1:0;if(p>=x.length)return null;while(p<x.length){var oi=i,w=1;for(var k=36;;k+=36){if(p>=x.length)return null;var c=x.charCodeAt(p++),v=c>=48&&c<58?c-22:(c>=97&&c<123?c-97:-1);if(v<0)return null;i+=v*w;var tt=k<=bi?1:(k>=bi+26?26:k-bi);if(v<tt)break;w*=36-tt;if(i>1e7)return null}bi=ad(i-oi,o.length+1,oi===0);n+=Math.floor(i/(o.length+1));i%=o.length+1;if(n>1114111||(n>=55296&&n<=57343))return null;o.splice(i,0,n);i++}return String.fromCodePoint.apply(null,o)}function okU(u){return /^[\p{L}\p{N}\p{M}-]+$/u.test(u)&&!/^[\p{M}-]|-$/u.test(u)&&/[^\x00-\x7f]/.test(u)&&u===u.normalize("NFC")&&u===u.toLowerCase()}function host(hh){var lb=hh.normalize("NFC").toLowerCase().split("."),o=[];if(lb.length<2)return null;for(var i=0;i<lb.length;i++){var L=lb[i];if(!L)return null;if(/^[a-z0-9-]+$/.test(L)){if(L.charAt(0)==="-"||L.charAt(L.length-1)==="-")return null;if(L.substr(2,2)==="--"){if(L.substr(0,4)!=="xn--")return null;var u=dec(L.slice(4));if(u===null||!okU(u)||enc(u)!==L.slice(4))return null}o.push(L)}else{if(!okU(L))return null;o.push("xn--"+enc(L))}if(o[i].length>63)return null}var tld=o[o.length-1];if(!/^[a-z]{2,63}$/.test(tld)&&tld.substr(0,4)!=="xn--")return null;var r=o.join(".");return r.length>253?null:r}if(typeof s!=="string"||/\s/.test(s))return null;var m=/^https:\/\/([^\/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i.exec(s);if(!m)return null;var auth=m[1],path=m[2]||"",query=m[3]||"",frag=m[4]||"";if(auth.indexOf("@")>=0)return null;var hp=/^([^:]+)(?::(\d{1,5}))?$/.exec(auth);if(!hp)return null;if(hp[2]!==undefined&&Number(hp[2])>65535)return null;var hn=host(hp[1]);if(!hn)return null;var norm="https://"+hn+(hp[2]!==undefined?":"+hp[2]:"")+path+query+frag;if(t!=="YouTube-Link")return norm;var seg=path.split("/").slice(1);if(seg.length>1&&seg[seg.length-1]==="")seg.pop();if(seg.indexOf("")>=0)return null;var id=null;if(hn==="youtu.be"){if(seg.length===1)id=seg[0]}else if(/^(?:www\.|m\.)?youtube\.com$/.test(hn)){if(seg.length===1&&seg[0]==="watch"){var q=query.replace(/^\?/,"").split("&"),c2=0;for(var i=0;i<q.length;i++){var kv=q[i].split("=");if(kv[0]==="v"){c2++;id=kv.slice(1).join("=")}}if(c2!==1)id=null}else if(seg.length===2&&(seg[0]==="shorts"||seg[0]==="embed"))id=seg[1]}if(id===null||!/^[A-Za-z0-9_-]{11}$/.test(id))return null;var k2=(norm.match(/(?:v=|youtu\.be\/|shorts\/|embed\/)([A-Za-z0-9_-]{11})/)||[])[1];return k2===id?norm:null}
if ((job.source_type === 'Artikel-Link' || job.source_type === 'YouTube-Link') && job.source) {
  const norm = checkLink(job.source_type, job.source);
  if (!norm) errors.push(job.source_type === 'YouTube-Link' ? 'Die Quelle muss ein YouTube-Video mit vollständiger Adresse sein (https://www.youtube.com/watch?v=..., https://youtu.be/... oder /shorts/...).' : 'Die Quelle muss eine vollständige Adresse mit https:// und Domain sein.');
  // Warum normalisieren: K1 sucht die Video-Kennung mit einem Muster, das auf Kleinschrift im Host angewiesen ist (youtu.be/).
  else job.source = norm;
}
if (job.source.length > 20000) errors.push('Die Quelle ist länger als 20.000 Zeichen.');
if (job.note.length > 1000) errors.push('Der Hinweis ist länger als 1.000 Zeichen.');

const ok = errors.length === 0;
// Warum der Hinweis in der Startmeldung: K1 protokolliert Kosten erst nach der Telegram-Entscheidung, die Seite lädt nicht von selbst neu.
// Warum ein Schalter: vor dem Aktivieren (Basic Auth, Aufrufrecht in K1) soll das Dashboard keinen echten Lauf auslösen.
const dispatch = cfg.dispatch_enabled === true;
let status_code = 200;
let response;
if (!ok) {
  status_code = 400;
  response = { ok: false, started: false, message: 'Auftrag nicht gestartet.', errors };
} else if (!dispatch) {
  response = { ok: true, started: false, message: `Probebetrieb: Der Auftrag für ${job.customer_code} ist gültig, wurde aber nicht an K1 übergeben. Zum Starten in der Konfiguration dispatch_enabled auf true setzen.` };
} else {
  status_code = 202;
  response = { ok: true, started: true, message: `Auftrag an K1 übergeben (${job.source_type}: ${job.topic}). Die Vorschau kommt zur Freigabe in Telegram. Kosten und Status erscheinen im Leitstand erst nach der Entscheidung in Telegram: dann unten bei „Kosten je Lauf“ auf „Neu laden“ klicken (Filter „alle“, falls der Lauf über einen Ersatzweg lief).` };
}
return [{ json: { ...job, start_k1: ok && dispatch, status_code, response } }];

// Zweck: baut die Dashboard-Seite aus Vorlage, Läufen, Tageswerten und Kunden. Alle Abfragen liefen serverseitig, im HTML steht kein Schlüssel.
const cfg = $('Konfiguration [Edit Fields]').first().json;
// Warum Vorlage aus Supabase: die Seite (rund 50 KB) liegt als nur lesende Funktion k1_dashboard_template() in der Datenbank und wird dort versioniert.
const raw = $('Vorlage laden [HTTP Request]').first().json.data;
let TEMPLATE = typeof raw === 'string' ? raw : '';
try { const p = JSON.parse(TEMPLATE); if (typeof p === 'string') TEMPLATE = p; } catch (e) { /* Antwort war schon reiner Text */ }
if (!TEMPLATE.includes('/*__DATA__*/null')) {
  throw new Error('Vorlage ohne Platzhalter erhalten (' + TEMPLATE.length + ' Zeichen), Seite nicht baubar.');
}
// Warum filtern: die Ladeknoten geben bei leerer Tabelle ein leeres Element weiter (alwaysOutputData), das darf nicht als Lauf zählen.
const runs = $('Läufe laden [HTTP Request]').all().map(i => i.json).filter(r => r && r.logged_at);
const dailyRaw = $('Tageswerte laden [HTTP Request]').all().map(i => i.json).filter(d => d && d.day);
const customers = $('Kunden laden [HTTP Request]').all().map(i => i.json).filter(c => c && c.kuerzel).map(c => ({
  code: c.kuerzel,
  name: c.name,
  active: c.aktiv === true,
  branding: {
    markenname: c.branding_pack?.markenname ?? null,
    farben: c.branding_pack?.farben ?? null,
    schriften: c.branding_pack?.schriften ?? null,
    // Warum Version: die Seite sendet sie beim Speichern als erwartete Version mit.
    version: Number(c.branding_pack?.version) || 0,
  },
}));

// Warum Lücken füllen: ein Tag ohne Lauf soll als leere Spalte sichtbar sein, sonst wirkt die Zeitachse gestaucht.
// Warum bis 60 Tage (14.10.2026): Woche und Monat im Verlauf brauchen mehr als 14 Tage; die Tagesansicht zeigt weiter nur die letzten 14.
const chartDays = Math.min(Math.max(Number(cfg.chart_days) || 14, 3), 60);
const today = $now.setZone('Europe/Berlin').startOf('day');
const byDay = Object.fromEntries(dailyRaw.map(d => [String(d.day).slice(0, 10), d]));
const known = Object.keys(byDay).sort();
let start = today.minus({ days: chartDays - 1 });
if (known.length) {
  const first = DateTime.fromISO(known[0], { zone: 'Europe/Berlin' });
  if (first > start) start = first;
}
const daily = [];
for (let d = start; d <= today; d = d.plus({ days: 1 })) {
  const key = d.toISODate();
  const v = byDay[key] || {};
  daily.push({
    day: key,
    runs: Number(v.runs) || 0,
    ok_count: Number(v.ok_count) || 0,
    fallback_count: Number(v.fallback_count) || 0,
    error_count: Number(v.error_count) || 0,
    open_count: Number(v.open_count) || 0,
    // Warum null statt 0: unbekannte Kosten sind keine Nullkosten.
    cost_usd: v.cost_usd == null ? null : Number(v.cost_usd),
    cost_unknown_count: Number(v.cost_unknown_count) || 0,
  });
}

const data = {
  generated_at: new Date().toISOString(),
  config: {
    dispatch_enabled: cfg.dispatch_enabled === true,
    branding_allowlist: String(cfg.branding_allowlist || '').split(',').map(s => s.trim()).filter(Boolean),
  },
  runs,
  daily,
  customers,
};

// Warum maskieren: ein "<" im JSON könnte ein </script> in einem Thema schließen (Testlauf 673 enthält genau so einen Text).
const BS = String.fromCharCode(92);
const safeJson = obj => JSON.stringify(obj).split('<').join(BS + 'u003c').split(String.fromCharCode(0x2028)).join(BS + 'u2028').split(String.fromCharCode(0x2029)).join(BS + 'u2029');

// Umbau 14.10.2026 (Abschlusspräsentation): die Vorlage in Supabase bleibt unverändert, die Ergänzungen setzt dieser Knoten ein.
// Warum Ersetzen mit Prüfung: fehlt eine Ankerstelle (Vorlage geändert), geht die unveränderte Vorlage raus (alles oder nichts), der Fehlschlag steht in patches_missing und im Seitenfuß.
const patchesMissing = [];
let html = TEMPLATE;
const patch = (name, anchor, replacement) => {
  const n = html.split(anchor).length - 1;
  if (n !== 1) { patchesMissing.push(name + ' (Anker ' + n + 'x)'); return; }
  html = html.replace(anchor, () => replacement);
};
// 1 Quellenart Research wie im n8n-Formular, Quelle dort optional wie bei Thema.
patch('form_research', '<option>Eigener Text</option></select>', '<option>Eigener Text</option><option>Research</option></select>');
patch('src_need', 'var need=t!=="Thema";', 'var need=t!=="Thema"&&t!=="Research";');
patch('src_hint', ':"(optional bei Quellenart Thema)"', ':"(optional bei Thema und Research)"');
patch('src_check', 'if(t!=="Thema"&&!src)srcMsg=', 'if(t!=="Thema"&&t!=="Research"&&!src)srcMsg=');
// 2 Verlauf: Auswahl Tag, Woche, Monat; zusammengefasst wird im Browser aus den Tageswerten.
patch('per_select', '<p class="sub" id="chartSub"></p>', '<p class="sub" id="chartSub"></p>\n<div class="tools per-tools"><label class="field-inline">Zeitraum<select id="fPer"><option value="day">Tag (14 Tage)</option><option value="week">Woche</option><option value="month">Monat</option></select></label><p class="total" id="perCost" aria-live="polite"></p></div>');
patch('per_label', 'function dayLabel(iso){return ', 'function dayLabel(iso){if(PER.mode!=="day")return perLabel(iso);return ');
patch('per_tip', 'new Date(d.day+"T12:00:00").toLocaleDateString("de-DE",{weekday:"short",day:"2-digit",month:"2-digit"})', 'perTip(d)');
patch('per_runs', 'drawChart($("#plotRuns"),daily,', 'drawChart($("#plotRuns"),viewDays(),');
patch('per_cost', 'drawChart($("#plotCost"),daily,', 'drawChart($("#plotCost"),viewDays(),');
patch('per_sub', '$("#chartSub").textContent="Die letzten "+daily.length+" Tage seit dem ersten Lauf. Zeigen Sie auf einen Balken für die Tageswerte.";', 'updPer();');
const PER_JS = [
  '/* Zeitraum Tag, Woche, Monat (14.10.2026) */',
  'var PER={mode:"day"};',
  'function isoWeek(iso){var d=new Date(iso+"T12:00:00Z");var wd=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-wd+3);var y=d.getUTCFullYear();var f=new Date(Date.UTC(y,0,4));return {y:y,w:1+Math.round(((d-f)/864e5-3+((f.getUTCDay()+6)%7))/7)}}',
  'function perKey(iso){if(PER.mode==="month")return iso.slice(0,7);var k=isoWeek(iso);return k.y+"-W"+(k.w<10?"0":"")+k.w}',
  'function perLabel(iso){if(PER.mode==="month")return new Date(iso.slice(0,7)+"-15T12:00:00").toLocaleDateString("de-DE",{month:"short",year:"2-digit"});return "KW "+isoWeek(iso).w}',
  'function perTip(d){if(PER.mode==="day")return new Date(d.day+"T12:00:00").toLocaleDateString("de-DE",{weekday:"short",day:"2-digit",month:"2-digit"});if(PER.mode==="month")return new Date(d.day.slice(0,7)+"-15T12:00:00").toLocaleDateString("de-DE",{month:"long",year:"numeric"});return "KW "+isoWeek(d.day).w+", ab "+new Date(d.day+"T12:00:00").toLocaleDateString("de-DE",{day:"2-digit",month:"2-digit"})}',
  'function viewDays(){if(PER.mode==="day")return daily.slice(-14);var m={},o=[];daily.forEach(function(d){var k=perKey(d.day);if(!m[k]){m[k]={day:d.day,runs:0,ok_count:0,fallback_count:0,error_count:0,open_count:0,cost_usd:null,cost_unknown_count:0};o.push(m[k])}var a=m[k];a.runs+=d.runs;a.ok_count+=d.ok_count;a.fallback_count+=d.fallback_count;a.error_count+=d.error_count;a.open_count+=d.open_count||0;a.cost_unknown_count+=d.cost_unknown_count||0;if(d.cost_usd!=null)a.cost_usd=(a.cost_usd||0)+Number(d.cost_usd)});return o}',
  "function updPer(){var v=viewDays();var name={day:\"Tage\",week:\"Wochen\",month:\"Monate\"}[PER.mode];var unit={day:\"Tag\",week:\"Woche\",month:\"Monat\"}[PER.mode];var fd=function(iso){return iso?new Date(iso+\"T12:00:00\").toLocaleDateString(\"de-DE\",{day:\"2-digit\",month:\"2-digit\"}):\"-\"};var first=daily.length?daily[0].day:null,last=daily.length?daily[daily.length-1].day:null;$(\"#chartSub\").textContent=\"Die letzten \"+v.length+\" \"+name+\" (geladen: \"+fd(first)+\" bis \"+fd(last)+(PER.mode===\"day\"?\"\":\", erste und letzte \"+(PER.mode===\"week\"?\"Woche\":\"Monat\")+\" können angeschnitten sein\")+\"). Zeigen Sie auf einen Balken für die Werte des Zeitraums.\";var c=0,u=0,r=0;v.forEach(function(d){if(d.cost_usd!=null)c+=Number(d.cost_usd);u+=d.cost_unknown_count||0;r+=d.runs});var ct=r===0?fmtUsd(0,4)+\" (kein Lauf)\":(u>=r?\"Kosten nicht erfasst (\"+u+\" Läufe ohne Kostenangabe)\":(u?fmtUsd(c,4)+\" bekannte Teilkosten (\"+u+\" von \"+r+\" Läufen nicht erfasst)\":fmtUsd(c,4)+\" insgesamt, im Mittel \"+fmtUsd(c/r,4)+\" je Lauf\"));$(\"#perCost\").textContent=\"Im gezeigten Zeitraum: \"+r+\" Läufe, \"+ct;var rt=$(\"#runsTotal\");if(rt)rt.textContent=r+\" Läufe in \"+v.length+\" \"+{day:\"Tagen\",week:\"Wochen\",month:\"Monaten\"}[PER.mode];var cto=$(\"#costTotal\");if(cto)cto.textContent=ct;var h1=$(\"#hRuns\");if(h1)h1.textContent=\"Läufe je \"+unit;var h2=$(\"#hCost\");if(h2)h2.textContent=\"Kosten je \"+unit}",
  'var fPer=document.getElementById("fPer");if(fPer){fPer.addEventListener("change",function(){PER.mode=fPer.value;if(daily.length){drawAll()}updPer()})}',
].join('\n') + '\n';
patch('per_js', 'function drawAll(){', PER_JS + 'function drawAll(){');
patch('per_h_runs', '<h3>Läufe je Tag</h3>', '<h3 id="hRuns">Läufe je Tag</h3>');
patch('per_h_cost', '<h3>Kosten je Tag</h3>', '<h3 id="hCost">Kosten je Tag</h3>');

// 4 Nachtrag 14.10.2026: Auslöser und Modellrolle je Lauf. Hauptmodell und Ersatzmodell stehen so in K1 Bk8PXBGm3gXMATK1 (Konfiguration: openai/gpt-4.1-nano, Ersatzmodell NVIDIA: nvidia/nemotron-3-super-120b-a12b).
// Warum checkLink (14.10.2026): EINE Prüffunktion, wortgleich in Auftrag prüfen; Host nach NFC in Kleinschrift und Punycode (wie der URL-Parser, Punycode-Etiketten nur gültig dekodierbar), Port bis 65535, YouTube nur mit exaktem v-Parameter bzw. Pfadsegment (11 Zeichen) und nur, wenn K1s Muster dieselbe Kennung findet.
// Warum aus error_short: der View k1_dashboard_runs hat kein eigenes Feld für den Auslöser, die Kennungen (E5, F1 bis F8, R1, R2, L4-Rückfall) stehen im Fehlertext, gekürzt auf 160 Zeichen.
const ROLE_FN = [
  'var ROLE_INFO={E5:"Eingabe ungültig",F1:"Quelle nicht lesbar",F2:"kein Video-Text",F3:"Hauptmodell ausgefallen",F4:"Bilddienst nicht aufgerufen",F5:"Rendern fehlgeschlagen",F6:"Kunde unbekannt",F7:"Freigabe-Frist abgelaufen",F8:"Abbruch nach dem Modellaufruf",R1:"Recherche ohne Ergebnis",R2:"keine aktuellen Posts",L4:"Layout-Rückfall"};',
  'function roleOf(r){var m=r.model||"";var t=r.error_short||"";if(/kein Modellaufruf/.test(t))return "kein Modellaufruf";if(!m)return "Modell nicht protokolliert";if(/nemotron|nvidia/i.test(m))return "Ersatzmodell "+m;if(/gpt-4[.]1-nano/i.test(m))return "Hauptmodell "+m;return m}',
